function waitForDrain(timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  return new Promise((resolve) => {
    const check = () => {
      if (inFlight.size === 0 || Date.now() >= deadline) {
        resolve(inFlight.size);
        return;
      }
      setTimeout(check, 50);
    };
    check();
  });
}

