let shuttingDown = false;
const inFlight = new Set();
const DRAIN_TIMEOUT_MS = 15000;

async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;
  console.error("received " + signal + ", draining " + inFlight.size + " in-flight requests");

  await server.notification({
    method: "notifications/message",
    params: { level: "warning", data: "server is shutting down shortly" }
  });

  const remaining = await waitForDrain(DRAIN_TIMEOUT_MS);
  if (remaining > 0) {
    console.error(remaining + " requests did not finish in time, proceeding anyway");
  }

  await closeResources();
  await transport.close();
  console.error("shutdown complete, exiting");
  process.exit(0);
}

process.on("SIGINT", () => shutdown("SIGINT"));
process.on("SIGTERM", () => shutdown("SIGTERM"));

async function closeResources() {
  const steps = [
    () => dbPool.end(),
    () => logStream.close(),
    () => cacheClient.disconnect()
  ];
  for (const step of steps) {
    try {
      await step();
    } catch (err) {
      console.error("cleanup step failed:", err.message);
    }
  }
}

let shuttingDown = false;
const inFlight = new Set();

async function handleReadReport(request) {
  if (shuttingDown) {
    throw new McpError(ErrorCode.InvalidRequest, "server is shutting down");
  }
  const marker = { id: request.id };
  inFlight.add(marker);
  try {
    const data = await fs.promises.readFile(request.params.arguments.path, "utf8");
    return { content: [{ type: "text", text: data }] };
  } finally {
    inFlight.delete(marker);
  }
}

async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;
  console.error(signal + " received, " + inFlight.size + " reads in flight");
  const start = Date.now();
  while (inFlight.size > 0 && Date.now() - start < 15000) {
    await new Promise((r) => setTimeout(r, 50));
  }
  console.error("drain finished, " + inFlight.size + " still pending");
  process.exit(0);
}

process.on("SIGTERM", () => shutdown("SIGTERM"));
